S=/private/tmp/claude-501/-Users-isabelguo-programming-project/dcaa4093-23e5-4084-ad25-d9da27488b5f/scratchpad; cat > $S/oligos.py <<'EOF'
import json, os, sys
J = "/Users/isabelguo/programming project/journal"; sys.path.insert(0, J)
from primer_design import design_primers, possible_designs, find_target, clean_sequence
from first_model_factor_specificity import reverse_complement
P = os.path.dirname(J)
line = next(l for l in open(P + "/website/example_data.js") if l.startswith("window.TEST_EXAMPLES = "))
tests = json.loads(line[len("window.TEST_EXAMPLES = "):].rstrip().rstrip(";"))

def sites(oligo, genome):
    """every site on either strand with <=3 mismatches: (pos 1-based, strand, mismatches)"""
    out = []
    for strand, pat in (("+", oligo), ("-", reverse_complement(oligo))):
        for i in range(len(genome) - len(pat) + 1):
            mm = sum(a != b for a, b in zip(genome[i:i+len(pat)], pat))
            if mm <= 3: out.append((i + 1, strand, mm))
    return out

rows = []
for n, t in enumerate(tests, 1):
    g = clean_sequence(t["genome"]); tg = clean_sequence(t["target"])
    seen = {}
    for a in (0, 1, 2):
        try: r = design_primers(g, tg, a)
        except ValueError: continue
        for k, d in enumerate(r["designs"], 1):
            seen.setdefault((d["forward"]["seq"], d["reverse"]["seq"], d["probe"]["seq"]), []).append(f"a{a} design {k}")
        if not r["designs"] and r["possible"]:
            s, e, _ = find_target(g, tg); d = possible_designs(g, s, e)[0]
            seen.setdefault((d["forward"]["seq"], d["reverse"]["seq"], d["probe"]["seq"]), []).append(f"a{a} top-ranked candidate (rejected)")
    for (f, rv, pr), why in seen.items():
        for role, o in (("F", f), ("R", rv), ("P", pr)):
            rows.append({"case": n, "why": why, "role": role, "seq": o, "sites": sites(o, g)})
json.dump({"tests": tests, "rows": rows}, open(sys.argv[1], "w"))
for r in rows:
    c = [sum(1 for s in r["sites"] if s[2] == m) for m in range(4)]
    print(r["case"], r["role"], r["seq"], "; ".join(r["why"]), "sites at 0/1/2/3 mm:", c)
EOF
python3 $S/oligos.py $S/oligos.json

