<script>
(function () {
  "use strict";
  var $ = function (id) { return document.getElementById(id); };
  var genomeBox = $("genome"), targetBox = $("target");

  function countBases(text) {
    return PrimerDesign.cleanSequence(text).length;
  }
  function updateCounts() {
    $("genome-count").textContent = countBases(genomeBox.value).toLocaleString() + " bases";
    $("target-count").textContent = countBases(targetBox.value).toLocaleString() + " bases";
  }
  genomeBox.addEventListener("input", updateCounts);
  targetBox.addEventListener("input", updateCounts);

  function wrapFasta(name, seq) {
    var lines = [">" + name];
    for (var i = 0; i < seq.length; i += 70) lines.push(seq.slice(i, i + 70));
    return lines.join("\n");
  }

  function loadExample() {
    var ex = window.EXAMPLE;
    genomeBox.value = wrapFasta(ex.genome_name, ex.genome);
    targetBox.value = wrapFasta(ex.target_name, ex.genome.slice(ex.target_start - 1, ex.target_end));
    updateCounts();
  }
  function run() {
    $("form").requestSubmit ? $("form").requestSubmit() : $("form").dispatchEvent(new Event("submit"));
  }
  $("example").addEventListener("click", function () { loadExample(); run(); });
  (window.TEST_EXAMPLES || []).forEach(function (test) {
    var button = el("button", "", test.label);
    button.type = "button";
    button.addEventListener("click", function () {
      genomeBox.value = wrapFasta(test.genome_name, test.genome);
      targetBox.value = wrapFasta(test.target_name, test.target);
      updateCounts();
      run();
    });
    $("example-buttons").appendChild(button);
  });

  $("genome-file").addEventListener("change", function (event) {
    var file = event.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function () { genomeBox.value = reader.result; updateCounts(); };
    reader.readAsText(file);
  });

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function notice(kind, label, text) {
    var box = el("div", "notice " + kind);
    box.appendChild(el("strong", "", label + " "));
    box.appendChild(document.createTextNode(text));
    return box;
  }

  function copyButton(text) {
    var button = el("button", "copy", "Copy");
    button.type = "button";
    button.setAttribute("aria-label", "Copy " + text);
    button.addEventListener("click", function () {
      var done = function () { button.textContent = "Copied"; setTimeout(function () { button.textContent = "Copy"; }, 1400); };
      if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(done, function () { selectText(button); });
      } else { selectText(button); }
    });
    return button;
  }
  function selectText(button) {
    var code = button.parentNode.querySelector("code");
    var range = document.createRange();
    range.selectNodeContents(code);
    var sel = window.getSelection();
    sel.removeAllRanges(); sel.addRange(range);
  }

  function gc(seq) { return PrimerDesign.gcPercent(seq); }

  function oligoRow(name, color, shown, ends, meta, orderAs) {
    var row = el("div", "oligo");
    var tag = el("div", "tag");
    var dot = el("span", "dot"); dot.style.background = color;
    tag.appendChild(dot); tag.appendChild(document.createTextNode(name));
    row.appendChild(tag);
    var seq = el("div", "seq");
    var line = el("span");
    line.appendChild(el("span", "end", ends[0] + "-"));
    line.appendChild(el("code", "", shown));
    line.appendChild(el("span", "end", "-" + ends[1]));
    seq.appendChild(line);
    seq.appendChild(copyButton(orderAs || shown));
    row.appendChild(seq);
    meta.forEach(function (text) { row.appendChild(el("div", "meta", text)); });
    return row;
  }

  function ampliconMap(d) {
    var ns = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(ns, "svg");
    svg.setAttribute("class", "map");
    svg.setAttribute("viewBox", "0 0 600 56");
    svg.setAttribute("preserveAspectRatio", "none");
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", "Map of the product: forward primer, probe and reverse primer positions");
    var start = d.product_start, len = d.product_length;
    var x = function (pos) { return 8 + (pos - start) / len * 584; };
    function rect(a, b, y, h, color) {
      var r = document.createElementNS(ns, "rect");
      r.setAttribute("x", x(a)); r.setAttribute("width", Math.max(2, x(b) - x(a)));
      r.setAttribute("y", y); r.setAttribute("height", h); r.setAttribute("rx", 2);
      r.setAttribute("fill", color);
      svg.appendChild(r);
    }
    var css = getComputedStyle(document.documentElement);
    rect(start, d.product_end, 25, 2, css.getPropertyValue("--line"));
    rect(d.forward.start, d.forward.end, 14, 9, css.getPropertyValue("--fwd"));
    rect(d.probe.start, d.probe.end, 22, 8, css.getPropertyValue("--probe"));
    rect(d.reverse.start, d.reverse.end, 29, 9, css.getPropertyValue("--rev"));
    function label(textValue, pos, anchor) {
      var t = document.createElementNS(ns, "text");
      t.setAttribute("x", x(pos)); t.setAttribute("y", 52); t.setAttribute("text-anchor", anchor);
      t.textContent = textValue;
      svg.appendChild(t);
    }
    label((start + 1).toLocaleString(), start, "start");
    label(d.product_length + " bp", start + len / 2, "middle");
    label(d.product_end.toLocaleString(), d.product_end, "end");
    return svg;
  }

  function designCard(d, number) {
    var card = el("article", "card design");
    var head = el("div", "design-head");
    head.appendChild(el("h2", "", "Design " + number));
    var pill = el("span", "pill" + (number === 1 ? " best" : ""), "penalty " + d.match_penalty.toFixed(2) + (number === 1 ? " · best match" : ""));
    head.appendChild(pill);
    card.appendChild(head);
    card.appendChild(ampliconMap(d));

    var css = getComputedStyle(document.documentElement);
    var f = d.forward, r = d.reverse, p = d.probe;
    card.appendChild(oligoRow("Forward", css.getPropertyValue("--fwd"), f.seq, ["5'", "3'"], [
      "Binds " + (f.start + 1).toLocaleString() + "–" + f.end.toLocaleString() + ", starts at " + (f.start + 1).toLocaleString() + " · " + f.seq.length + " nt · GC " + gc(f.seq),
    ]));
    card.appendChild(oligoRow("Reverse", css.getPropertyValue("--rev"), r.seq.split("").reverse().join(""), ["3'", "5'"], [
      "Binds " + (r.start + 1).toLocaleString() + "–" + r.end.toLocaleString() + ", 5' end at " + r.end.toLocaleString() + " · " + r.seq.length + " nt · GC " + gc(r.seq),
      "Order as 5'-" + r.seq + "-3' (Copy gives this)",
    ], r.seq));
    card.appendChild(oligoRow("Probe", css.getPropertyValue("--probe"), p.seq, ["5'", "3'"], [
      "Binds " + (p.start + 1).toLocaleString() + "–" + p.end.toLocaleString() + " · " + p.seq.length + " nt · GC " + gc(p.seq),
    ]));
    card.appendChild(el("div", "product-line",
      "Product " + (d.product_start + 1).toLocaleString() + "–" + d.product_end.toLocaleString() +
      ", " + d.product_length + " bp: the only product the specificity model finds in the whole genome."));
    return card;
  }

  function render(result, allowance) {
    var out = $("results");
    out.textContent = "";
    var t = result.target;
    var range = result.product_range;
    var summary = el("div", "summary");
    var line1 = el("div");
    line1.appendChild(document.createTextNode("Target found at "));
    line1.appendChild(el("b", "", (t.start + 1).toLocaleString() + "–" + t.end.toLocaleString()));
    line1.appendChild(document.createTextNode(" (" + t.strand + " strand, " + (t.end - t.start).toLocaleString() + " bases) in a " + result.genome_length.toLocaleString() + "-base genome."));
    summary.appendChild(line1);
    summary.appendChild(el("div", "", result.possible.toLocaleString() + " possible designs from " + range[0] + " to " + range[1] + " bp (shorter ranks higher); " + result.checked + " checked against the whole genome with mismatch allowance " + allowance + "."));
    out.appendChild(summary);
    result.warnings.forEach(function (w) { out.appendChild(notice("warn", "Warning:", w)); });
    if (!result.designs.length) {
      if (result.possible) out.appendChild(notice("err", "No design:", "every candidate also binds somewhere else in the genome within the mismatch allowance. Try a lower allowance or another target."));
      return;
    }
    result.designs.forEach(function (d, i) { out.appendChild(designCard(d, i + 1)); });
  }

  $("form").addEventListener("submit", function (event) {
    event.preventDefault();
    var allowance = parseInt($("allowance").value, 10);
    var shortest = Number($("product-min").value), longest = Number($("product-max").value);
    var button = $("run");
    button.disabled = true;
    $("status").textContent = "Designing…";
    $("results").textContent = "";
    setTimeout(function () {
      var started = performance.now();
      try {
        var result = PrimerDesign.designPrimers(genomeBox.value, targetBox.value, allowance, shortest, longest);
        render(result, allowance);
        $("status").textContent = "Done in " + ((performance.now() - started) / 1000).toFixed(1) + " s.";
      } catch (error) {
        $("results").appendChild(notice("err", "Error:", error.message));
        $("status").textContent = "";
      }
      button.disabled = false;
    }, 30);
  });

  // Open in a working state: the example loaded and designed.
  loadExample();
  run();
})();
</script>

